struct Catalog {
    locale: &'static str,
    messages: &'static [(&'static str, &'static str)],
}

static CATALOGS: &[Catalog] = &[
    Catalog {
        locale: "de",
        messages: MESSAGES_DE,
    },
    Catalog {
        locale: "en",
        messages: MESSAGES_EN,
    },
    Catalog {
        locale: "es",
        messages: MESSAGES_ES,
    },
    Catalog {
        locale: "fr",
        messages: MESSAGES_FR,
    },
    Catalog {
        locale: "it",
        messages: MESSAGES_IT,
    },
    Catalog {
        locale: "ja",
        messages: MESSAGES_JA,
    },
    Catalog {
        locale: "ko",
        messages: MESSAGES_KO,
    },
    Catalog {
        locale: "pt_BR",
        messages: MESSAGES_PT_BR,
    },
    Catalog {
        locale: "ru",
        messages: MESSAGES_RU,
    },
    Catalog {
        locale: "uk",
        messages: MESSAGES_UK,
    },
    Catalog {
        locale: "zh_Hans_CN",
        messages: MESSAGES_ZH_HANS_CN,
    },
];

/// Plural form selection, copied from the Plural-Forms header of each
/// upstream catalog.
fn plural_index(locale: &str, n: u64) -> usize {
    match locale {
        "de" => {
            if n == 1 {
                0
            } else {
                1
            }
        }
        "en" => {
            if n == 1 {
                0
            } else {
                1
            }
        }
        "es" => {
            if n == 1 {
                0
            } else {
                1
            }
        }
        "fr" => {
            if n > 1 {
                1
            } else {
                0
            }
        }
        "it" => {
            if n == 1 {
                0
            } else {
                1
            }
        }
        "ja" => 0,
        "ko" => 0,
        "pt_BR" => {
            if n > 1 {
                1
            } else {
                0
            }
        }
        "ru" => {
            if n % 10 == 1 && n % 100 != 11 {
                0
            } else if n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14) {
                1
            } else if n % 10 == 0
                || (n % 10 >= 5 && n % 10 <= 9)
                || (n % 100 >= 11 && n % 100 <= 14)
            {
                2
            } else {
                3
            }
        }
        "uk" => {
            if n % 10 == 1 && n % 100 != 11 {
                0
            } else if n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14) {
                1
            } else if n % 10 == 0
                || (n % 10 >= 5 && n % 10 <= 9)
                || (n % 100 >= 11 && n % 100 <= 14)
            {
                2
            } else {
                3
            }
        }
        "zh_Hans_CN" => 0,
        _ => {
            if n == 1 {
                0
            } else {
                1
            }
        }
    }
}

/// The (singular, plural) pairs the UI uses with ngettext.
pub static NGETTEXT_PAIRS: &[(&str, &str)] = &[("Engine", "Engines"), ("Time", "Times")];

/// Plural form translations.  The upstream catalogs contain no msgid_plural
/// entries, so this table stays empty and ngettext falls back to the English
/// plural for every form except the singular (which uses the catalog entry).
fn plural_forms(_locale: &str, _msgid: &str) -> Option<&'static [&'static str]> {
    None
}

/// The catalog of a locale, or 'en' for an unknown one.
pub fn for_locale(locale: &str) -> Translator {
    Translator {
        locale: match_locale(locale),
    }
}

/// Resolve a (possibly regional) locale tag onto a shipped locale.
fn match_locale(locale: &str) -> &'static str {
    let normalized = locale.trim().replace('-', "_");
    if normalized.is_empty() {
        return "en";
    }
    for candidate in SHIPPED_LOCALES {
        if candidate.eq_ignore_ascii_case(&normalized) {
            return candidate;
        }
    }
    let language = normalized.split('_').next().unwrap_or("");
    if language.eq_ignore_ascii_case("zh") {
        return "zh_Hans_CN";
    }
    for candidate in SHIPPED_LOCALES {
        if candidate.eq_ignore_ascii_case(language) {
            return candidate;
        }
    }
    "en"
}

/// The locales the port ships translations for.
pub fn available_locales() -> &'static [&'static str] {
    SHIPPED_LOCALES
}

impl Translator {
    /// The resolved locale of this translator.
    pub fn locale(&self) -> &'static str {
        self.locale
    }

    fn catalog(&self) -> Option<&'static Catalog> {
        CATALOGS
            .iter()
            .find(|catalog| catalog.locale == self.locale)
    }

    /// The translation of msgid, or msgid itself when the catalog has none.
    pub fn gettext<'a>(&'a self, msgid: &'a str) -> &'a str {
        match self.catalog() {
            Some(catalog) => catalog
                .messages
                .iter()
                .find(|(key, _)| *key == msgid)
                .map(|(_, value)| *value)
                .unwrap_or(msgid),
            None => msgid,
        }
    }

    /// The singular or plural translation of singular / plural for n.
    pub fn ngettext<'a>(&'a self, singular: &'a str, plural: &'a str, n: u64) -> &'a str {
        let index = plural_index(self.locale, n);
        if index == 0 {
            return self.gettext(singular);
        }
        if let Some(forms) = plural_forms(self.locale, singular) {
            if let Some(form) = forms.get(index) {
                if !form.is_empty() {
                    return form;
                }
            }
        }
        plural
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn english_is_the_fallback_for_unknown_locales() {
        let translator = for_locale("xx");
        assert_eq!(translator.locale(), "en");
        assert_eq!(translator.gettext("Preferences"), "Preferences");
    }

    #[test]
    fn regional_tags_resolve_onto_a_shipped_locale() {
        assert_eq!(for_locale("de-DE").locale(), "de");
        assert_eq!(for_locale("pt-BR").locale(), "pt_BR");
        assert_eq!(for_locale("zh-CN").locale(), "zh_Hans_CN");
        assert_eq!(for_locale("ja_JP").locale(), "ja");
    }

    #[test]
    fn available_locales_contain_the_source_locale() {
        let locales = available_locales();
        assert!(locales.contains(&"en"));
        assert!(locales.contains(&"ja"));
        assert!(locales.contains(&"de"));
        assert!(locales.contains(&"zh_Hans_CN"));
    }

    #[test]
    fn ngettext_uses_the_english_plural_for_the_plural_form() {
        let translator = for_locale("en");
        assert_eq!(translator.ngettext("Engine", "Engines", 1), "Engine");
        assert_eq!(translator.ngettext("Engine", "Engines", 2), "Engines");
    }

    #[test]
    fn ngettext_follows_the_locale_plural_rule() {
        // Japanese has nplurals=1: every count uses the singular form.
        let japanese = for_locale("ja");
        let singular = japanese.gettext("Engine");
        assert_eq!(japanese.ngettext("Engine", "Engines", 1), singular);
        assert_eq!(japanese.ngettext("Engine", "Engines", 5), singular);
        // French uses the plural for n > 1 (nplurals=2).
        let french = for_locale("fr");
        assert_eq!(
            french.ngettext("Engine", "Engines", 1),
            french.gettext("Engine")
        );
        assert_eq!(french.ngettext("Engine", "Engines", 2), "Engines");
    }

    #[test]
    fn every_ngettext_pair_is_translatable() {
        let translator = for_locale("ja");
        for (singular, plural) in NGETTEXT_PAIRS {
            let one = translator.ngettext(singular, plural, 1);
            let many = translator.ngettext(singular, plural, 7);
            assert!(!one.is_empty() && !many.is_empty());
            // nplurals=1: both forms come from the catalog entry.
            assert_eq!(one, many);
        }
    }

    #[test]
    fn translations_come_from_the_upstream_catalogs() {
        assert_eq!(for_locale("de").gettext("Preferences"), "Einstellungen");
        assert_eq!(for_locale("de").gettext("About"), "Über");
        assert_ne!(for_locale("ja").gettext("Preferences"), "Preferences");
        // An unknown msgid is returned unchanged.
        assert_eq!(for_locale("de").gettext("no such msgid"), "no such msgid");
    }
}
